(() => {
  const root = document.getElementById("agent-density-preview");
  if (!root) return;
  // These optional helpers are appended by the visualization host, not this file.
  // Give only these exact resources an explicit offline rendering path. Other
  // script errors and application exceptions remain visible to the host reporter.
  const optionalHelpers = new Map([
    ["https://unpkg.com/@floating-ui/core@1.7.3/dist/floating-ui.core.umd.min.js", "floating-core"],
    ["https://unpkg.com/@floating-ui/dom@1.7.4/dist/floating-ui.dom.umd.min.js", "floating-dom"],
    ["https://unpkg.com/lucide@1.17.0/dist/umd/lucide.js", "lucide"]
  ]);
  const missingHelpers = new Set();
  const iconText = {
    "wifi":"◔", "signal":"▥", "battery":"▰", "chevron-down":"⌄",
    "settings":"⚙", "ellipsis":"⋯", "maximize-2":"⤢",
    "sliders-horizontal":"☷", "chevron-right":"›", "circle-check":"✓",
    "bot":"◇", "arrow-up-right":"↗", "plus":"+", "arrow-up":"↑",
    "house":"⌂", "layout-grid":"▦", "images":"▧", "x":"×",
    "message-circle":"◯", "messages-square":"▣", "trash-2":"⌫",
    "check":"✓", "list":"☰", "chevron-left":"‹"
  };
  function renderTextIcons() {
    root.querySelectorAll("i[data-lucide]").forEach((icon) => {
      const glyph = iconText[icon.dataset.lucide];
      if (glyph && !icon.textContent) icon.textContent = glyph;
    });
  }
  function handleOptionalScript(script) {
    if (!(script instanceof HTMLScriptElement)) return;
    const helper = optionalHelpers.get(script.src);
    if (!helper || typeof script.onerror === "function") return;
    // No tooltips are used by this preview. If the host's tooltip library fails,
    // nothing essential is lost; icon placeholders retain readable text glyphs.
    script.onerror = () => {
      missingHelpers.add(helper);
      root.dataset.optionalHelperFallback = Array.from(missingHelpers).sort().join(",");
      renderTextIcons();
    };
  }
  const helperObserver = new MutationObserver((records) => {
    records.forEach((record) => {
      record.addedNodes.forEach((node) => {
        if (node.nodeType !== Node.ELEMENT_NODE) return;
        handleOptionalScript(node);
        node.querySelectorAll("script[src]").forEach(handleOptionalScript);
      });
    });
    renderTextIcons();
  });
  // Install before the parser encounters the host-injected optional resources.
  helperObserver.observe(document, { childList:true, subtree:true });
  document.querySelectorAll("script[src]").forEach(handleOptionalScript);
  renderTextIcons();
  window.addEventListener("pagehide", () => helperObserver.disconnect(), { once:true });
  const phones = Array.from(root.querySelectorAll(".ad-phone"));
  const translations = [
    ["bad hands", "手部画得差"],
    ["deformed hands", "手部变形"],
    ["extra fingers", "多指"],
    ["fused fingers", "手指粘连"],
    ["malformed hand", "手的形状畸形"],
    ["mutated hands", "手部畸变"]
  ];
  const phoneState = new Map();
  let activeTrigger = null;
  const esc = (value) => String(value).replace(/[&<>"']/g, (char) => ({ "&":"&amp;", "<":"&lt;", ">":"&gt;", '"':"&quot;", "'":"&#39;" }[char]));
  const saved = () => {
    const state = window.openai?.widgetState;
    return state && typeof state === "object" ? state : {};
  };
  const restore = (snapshot) => {
    const ui = snapshot?.privateContent;
    if (!ui || typeof ui !== "object") return;
    phones.forEach((phone) => {
      const id = phone.dataset.design;
      const settings = ui[id];
      if (!settings || typeof settings !== "object") return;
      const state = phoneState.get(phone);
      if (typeof settings.message === "string") phone.querySelector('input[name="message"]').value = settings.message.slice(0, 2000);
      if (typeof settings.prompt === "string") state.prompt = settings.prompt.slice(0, 2000);
      if (settings.workspace === "chat" || settings.workspace === "draw") applyWorkspace(phone, settings.workspace);
      if (settings.inputMode === "chat" || settings.inputMode === "draw") applyInputMode(phone, settings.inputMode);
    });
  };
  const remember = () => {
    const privateContent = {};
    phones.forEach((phone) => {
      privateContent[phone.dataset.design] = { ...phoneState.get(phone), message:phone.querySelector('input[name="message"]').value.slice(0,2000) };
    });
    if (window.openai?.setWidgetState) window.openai.setWidgetState({ modelContent:{ preview:"Agent 页面密度优化", variants:["生成优先","对话优先"] }, privateContent }).catch(() => {});
  };
  const refreshIcons = () => {
    renderTextIcons();
    if (typeof globalThis.lucide?.createIcons === "function") globalThis.lucide.createIcons({ attrs:{ width:20, height:20 } });
  };
  function applyWorkspace(phone, workspace) {
    phoneState.get(phone).workspace = workspace;
    const draw = phone.querySelector(".ad-draw-view");
    const chat = phone.querySelector(".ad-chat-view");
    if (draw) draw.hidden = workspace !== "draw";
    if (chat) chat.hidden = workspace !== "chat";
    phone.querySelectorAll("[data-workspace]").forEach((button) => button.setAttribute("aria-pressed", String(button.dataset.workspace === workspace)));
  }
  function applyInputMode(phone, mode) {
    phoneState.get(phone).inputMode = mode;
    phone.querySelectorAll("[data-input-mode]").forEach((button) => button.setAttribute("aria-pressed", String(button.dataset.inputMode === mode)));
  }
  function announce(phone, text) {
    phone.querySelector(".ad-local-message").textContent = text;
  }
  function sendMessage(phone) {
    const input = phone.querySelector('input[name="message"]');
    const value = input.value.trim();
    if (!value) { input.focus(); return; }
    announce(phone, `示例消息已接收：${value.slice(0,200)}`);
    input.value = "";
    remember();
  }
  function closeSheet(phone) {
    const overlay = phone.querySelector(".ad-overlay");
    overlay.hidden = true;
    overlay.replaceChildren();
    phone.querySelector(".ad-page").inert = false;
    if (activeTrigger?.isConnected) activeTrigger.focus({ preventScroll:true });
    activeTrigger = null;
  }
  function showSheet(phone, title, content, kind) {
    const overlay = phone.querySelector(".ad-overlay");
    const titleId = `ad-sheet-${phone.dataset.design}`;
    phone.querySelector(".ad-page").inert = true;
    overlay.innerHTML = `<section class="ad-sheet" role="dialog" aria-modal="true" aria-labelledby="${titleId}" data-panel="${kind}"><div class="ad-handle" aria-hidden="true"></div><div class="ad-sheet-heading"><h2 id="${titleId}">${esc(title)}</h2><button type="button" class="ad-icon cursor-interaction" data-action="close" aria-label="关闭面板"><i data-lucide="x" aria-hidden="true"></i></button></div>${content}</section>`;
    overlay.hidden = false;
    refreshIcons();
    overlay.querySelector('[data-action="close"]').focus({ preventScroll:true });
  }
  function openAction(phone, action) {
    if (action === "negative") {
      const items = translations.map(([word, translation]) => `<div><dt>${esc(word)}</dt><dd>${esc(translation)}</dd></div>`).join("");
      showSheet(phone, "反向词详情", `<p>已写入工作流反向输入 · 1 项<br>中文释义仅供查看</p><dl class="ad-detail-list">${items}</dl>`, action);
    } else if (action === "settings") {
      const prompt = phoneState.get(phone).prompt;
      showSheet(phone, "绘图设置", `<dl class="ad-detail-list"><div><dt>当前配置</dt><dd>安卓anima</dd></div><div><dt>画风 / 画师</dt><dd>沿用当前设置</dd></div></dl><label>提示词<textarea name="prompt">${esc(prompt)}</textarea></label><button type="button" class="ad-primary cursor-interaction" data-action="save-settings">保存设置</button>`, action);
    } else if (action === "preview") {
      showSheet(phone, "生成预览", `<div class="ad-art ad-sheet-picture" role="img" aria-label="暖色山峦预览示意图"><span class="ad-sun"></span><span class="ad-mountain ad-far"></span><span class="ad-mountain ad-near"></span><span class="ad-window"></span></div><p>正在生成 · K采样器 · 16%</p>`, action);
    } else if (action === "sessions") {
      showSheet(phone, "会话", `<button type="button" class="ad-menu-item cursor-interaction" data-action="close"><i data-lucide="message-circle" aria-hidden="true"></i>新会话 · 当前</button><button type="button" class="ad-menu-item cursor-interaction" data-action="new-session"><i data-lucide="plus" aria-hidden="true"></i>创建新会话</button>`, action);
    } else if (action === "menu") {
      showSheet(phone, "会话操作", `<button type="button" class="ad-menu-item cursor-interaction" data-action="sessions"><i data-lucide="messages-square" aria-hidden="true"></i>会话记录</button><button type="button" class="ad-menu-item cursor-interaction" data-action="page-settings"><i data-lucide="settings" aria-hidden="true"></i>Agent 设置</button><button type="button" class="ad-menu-item ad-destructive cursor-interaction" data-action="confirm-clear"><i data-lucide="trash-2" aria-hidden="true"></i>清空当前对话</button>`, action);
    } else if (action === "confirm-clear") {
      showSheet(phone, "清空当前对话？", `<p>确认后清空当前会话的消息。</p><button type="button" class="ad-menu-item cursor-interaction" data-action="close">保留对话</button><button type="button" class="ad-menu-item ad-destructive cursor-interaction" data-action="clear"><i data-lucide="trash-2" aria-hidden="true"></i>确认清空</button>`, action);
    } else if (action === "context") {
      showSheet(phone, "dsh", `<button type="button" class="ad-menu-item cursor-interaction" data-action="close"><i data-lucide="check" aria-hidden="true"></i>dsh · 当前选择</button>`, action);
    } else if (action === "add") {
      showSheet(phone, "添加内容", `<button type="button" class="ad-menu-item cursor-interaction" data-action="settings"><i data-lucide="sliders-horizontal" aria-hidden="true"></i>绘图设置</button><button type="button" class="ad-menu-item cursor-interaction" data-action="negative"><i data-lucide="list" aria-hidden="true"></i>反向词详情</button>`, action);
    }
  }
  phones.forEach((phone) => {
    phoneState.set(phone, { workspace:"draw", inputMode:"draw", prompt:"优化手部细节，手指自然。" });
    phone.addEventListener("click", (event) => {
      const button = event.target.closest("button");
      if (!button || !phone.contains(button)) return;
      if (button.dataset.workspace) {
        applyWorkspace(phone, button.dataset.workspace); remember(); return;
      }
      if (button.dataset.inputMode) {
        applyInputMode(phone, button.dataset.inputMode); remember(); return;
      }
      const action = button.dataset.action;
      if (!action) return;
      if (action === "send") { sendMessage(phone); return; }
      if (action === "close") { closeSheet(phone); return; }
      if (action === "page-settings") {
        if (!phone.querySelector(".ad-overlay").hidden) closeSheet(phone);
        announce(phone, "已选择 Agent 设置（页面跳转示意）。"); return;
      }
      if (action === "save-settings") {
        phoneState.get(phone).prompt = phone.querySelector('textarea[name="prompt"]').value.slice(0,2000);
        closeSheet(phone); announce(phone, "绘图设置已保存。"); remember(); return;
      }
      if (action === "new-session") {
        phone.querySelector('input[name="message"]').value = "";
        closeSheet(phone); announce(phone, "已创建新的示例会话。"); remember(); return;
      }
      if (action === "clear") {
        closeSheet(phone);
        phone.querySelectorAll(".ad-user-message,.ad-agent-message").forEach((message) => message.hidden = true);
        announce(phone, "当前示例对话已清空。");
        remember(); return;
      }
      if (action === "nav") { announce(phone, `已选择“${button.dataset.label}”（页面跳转示意）。`); return; }
      if (!phone.querySelector(".ad-overlay").hidden) {
        openAction(phone, action);
      } else {
        activeTrigger = button;
        openAction(phone, action);
      }
    });
    phone.querySelector(".ad-composer").addEventListener("submit", (event) => {
      event.preventDefault();
      sendMessage(phone);
    });
    phone.querySelector('input[name="message"]').addEventListener("keydown", (event) => {
      if (event.key === "Enter" && !event.isComposing) {
        event.preventDefault();
        sendMessage(phone);
      }
    });
    phone.querySelector('input[name="message"]').addEventListener("change", remember);
    phone.querySelector(".ad-overlay").addEventListener("click", (event) => {
      if (event.target === event.currentTarget) closeSheet(phone);
    });
    phone.addEventListener("keydown", (event) => {
      const overlay = phone.querySelector(".ad-overlay");
      if (overlay.hidden) return;
      if (event.key === "Escape") { event.preventDefault(); closeSheet(phone); }
      if (event.key === "Tab") {
        const nodes = Array.from(overlay.querySelectorAll("button:not([disabled]),textarea,input,select"));
        const first = nodes[0], last = nodes[nodes.length - 1];
        if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
        if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
      }
    });
  });
  restore(saved());
  window.addEventListener("openai:set_globals", (event) => {
    if (event.detail?.globals?.widgetState) restore(event.detail.globals.widgetState);
  });
  const design = { appearance:"system", radius:22 };
  function updateDesign() {
    phones.forEach((phone) => {
      phone.style.setProperty("--ad-radius", `${design.radius}px`);
      phone.style.colorScheme = design.appearance === "system" ? "light dark" : design.appearance;
    });
  }
  updateDesign();
  if (globalThis.Tweak) {
    const tweak = new Tweak({ container:root, onChange:updateDesign });
    tweak.addSelect(design, "appearance", { label:"外观", options:[{label:"跟随系统",value:"system"},{label:"深色",value:"dark"},{label:"浅色",value:"light"}] });
    tweak.addSlider(design, "radius", { label:"内容圆角", min:12, max:28, step:2, unit:"px" });
  }
  root.dataset.previewReady = "true";
})();

