    phoneState.set(phone, { workspace:"draw", inputMode:"draw", prompt:"优化手部细节，手指自然。" });
    phone.addEventListener("click", (event) => {
      const button = event.target.closest("button");
      if (!button || !phone.contains(button)) return;
      if (button.dataset.workspace) {
        applyWorkspace(phone, button.dataset.workspace); remember(); return;
      }
      if (button.dataset.inputMode) {
        applyInputMode(phone, button.dataset.inputMode); remember(); return;
      }
      const action = button.dataset.action;
      if (!action) return;
      if (action === "send") { sendMessage(phone); return; }
      if (action === "close") { closeSheet(phone); return; }
      if (action === "page-settings") {
        if (!phone.querySelector(".ad-overlay").hidden) closeSheet(phone);
        announce(phone, "已选择 Agent 设置（页面跳转示意）。"); return;
      }
      if (action === "save-settings") {
        phoneState.get(phone).prompt = phone.querySelector('textarea[name="prompt"]').value.slice(0,2000);
        closeSheet(phone); announce(phone, "绘图设置已保存。"); remember(); return;
      }
      if (action === "new-session") {
        phone.querySelector('input[name="message"]').value = "";
        closeSheet(phone); announce(phone, "已创建新的示例会话。"); remember(); return;
      }
      if (action === "clear") {
        closeSheet(phone);
        phone.querySelectorAll(".ad-user-message,.ad-agent-message").forEach((message) => message.hidden = true);
        announce(phone, "当前示例对话已清空。");
        remember(); return;
      }
      if (action === "nav") { announce(phone, `已选择“${button.dataset.label}”（页面跳转示意）。`); return; }
      if (!phone.querySelector(".ad-overlay").hidden) {
        openAction(phone, action);
      } else {
        activeTrigger = button;
        openAction(phone, action);
      }
    });
    phone.querySelector(".ad-composer").addEventListener("submit", (event) => {
      event.preventDefault();
      sendMessage(phone);
    });
    phone.querySelector('input[name="message"]').addEventListener("keydown", (event) => {
      if (event.key === "Enter" && !event.isComposing) {
        event.preventDefault();
        sendMessage(phone);
      }
    });
    phone.querySelector('input[name="message"]').addEventListener("change", remember);
    phone.querySelector(".ad-overlay").addEventListener("click", (event) => {
      if (event.target === event.currentTarget) closeSheet(phone);
    });
    phone.addEventListener("keydown", (event) => {
      const overlay = phone.querySelector(".ad-overlay");
      if (overlay.hidden) return;
      if (event.key === "Escape") { event.preventDefault(); closeSheet(phone); }
      if (event.key === "Tab") {
        const nodes = Array.from(overlay.querySelectorAll("button:not([disabled]),textarea,input,select"));
        const first = nodes[0], last = nodes[nodes.length - 1];
        if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
        if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
      }
    });
  });
  restore(saved());
  window.addEventListener("openai:set_globals", (event) => {
    if (event.detail?.globals?.widgetState) restore(event.detail.globals.widgetState);
  });
  const design = { appearance:"system", radius:22 };
  function updateDesign() {
    phones.forEach((phone) => {
      phone.style.setProperty("--ad-radius", `${design.radius}px`);
      phone.style.colorScheme = design.appearance === "system" ? "light dark" : design.appearance;
    });
  }
  updateDesign();
  if (globalThis.Tweak) {
    const tweak = new Tweak({ container:root, onChange:updateDesign });
    tweak.addSelect(design, "appearance", { label:"外观", options:[{label:"跟随系统",value:"system"},{label:"深色",value:"dark"},{label:"浅色",value:"light"}] });
    tweak.addSlider(design, "radius", { label:"内容圆角", min:12, max:28, step:2, unit:"px" });
  }
  root.dataset.previewReady = "true";
})();

